cd ~/academy-labs/g8-1 && cat > git-serve.mjs <<'EOF'
// A tiny git server: serves the bare repos in ./served over smart HTTP, like GitHub does.
import { createServer } from "node:http";
import { spawn, execSync } from "node:child_process";
import { resolve } from "node:path";

const port = Number(process.argv[2] ?? 8765);
const backend = `${execSync("git --exec-path").toString().trim()}/git-http-backend`;

createServer((req, res) => {
  const url = new URL(req.url, "http://localhost");
  const cgi = spawn(backend, [], { env: {
    GIT_PROJECT_ROOT: resolve("served"), GIT_HTTP_EXPORT_ALL: "1", REQUEST_METHOD: req.method,
    PATH_INFO: url.pathname, QUERY_STRING: url.search.slice(1),
    CONTENT_TYPE: req.headers["content-type"] ?? "", CONTENT_LENGTH: req.headers["content-length"] ?? "",
    HTTP_CONTENT_ENCODING: req.headers["content-encoding"] ?? "", GIT_PROTOCOL: req.headers["git-protocol"] ?? "",
  } });
  req.pipe(cgi.stdin);
  let head = Buffer.alloc(0), sent = false;
  cgi.stdout.on("data", (chunk) => {
    if (sent) return res.write(chunk);
    head = Buffer.concat([head, chunk]);
    const end = head.indexOf("\r\n\r\n");
    if (end < 0) return;
    const headers = Object.fromEntries(head.subarray(0, end).toString().split("\r\n")
      .map((l) => [l.slice(0, l.indexOf(":")), l.slice(l.indexOf(":") + 1).trim()]));
    res.writeHead(Number((headers.Status ?? "200").split(" ")[0]), headers);
    res.write(head.subarray(end + 4));
    sent = true;
  });
  cgi.stdout.on("end", () => res.end());
}).listen(port, () => console.log(`git server on http://localhost:${port}/  (repos in ./served)`));
EOF
node git-serve.mjs

